def test_wrap_with_uses_context_manager():
    log = []

    class CM:
        def __enter__(self):
            log.append("enter")
            return self

        def __exit__(self, *exc):
            log.append("exit")

    @wrap_with(CM())
    def f():
        log.append("call")
        return "result"

    assert f() == "result"
    assert log == ["enter", "call", "exit"]


def test_wrap_with_context_manager_with_error():
    log = []

    class CM:
        def __enter__(self):
            return self

        def __exit__(self, exc_type, exc, tb):
            log.append(exc_type)
            return False

    @wrap_with(CM())
    def f():
        raise ValueError("x")

    with pytest.raises(ValueError):
        f()
    assert log == [ValueError]


def test_wrap_with_single_arg_decorator_form():
    log = []

    class CM:
        def __enter__(self):
            log.append("enter")
            return self

        def __exit__(self, *exc):
            log.append("exit")

    @wrap_with
    def f():
        return 1

    # bare wrap_with call applied to a context manager instance (no parens style)
    # Here @wrap_with is not the usual usage, so test explicit ctx wrapping.
    @wrap_with(CM())
    def g():
        log.append("body")
        return 2

    assert g() == 2
    assert log == ["enter", "body", "exit"]
